import type { UIMessage } from '@nao/backend/chat';
import { marked, Renderer } from 'marked';

import { type ChatMetadata, getMessageMarkdown, type SerializeOptions } from './serialize-message';

/** Triggers a browser download of a text file with the given content. */
export function downloadTextFile(filename: string, content: string, mimeType: string): void {
	const blob = new Blob([content], { type: mimeType });
	const url = URL.createObjectURL(blob);
	const link = document.createElement('a');
	link.href = url;
	link.download = filename;
	document.body.appendChild(link);
	link.click();
	link.remove();
	URL.revokeObjectURL(url);
}

/** Opens a print window rendering the conversation as a styled document so the user can save it as a PDF. */
export function printChatAsPdf(metadata: ChatMetadata, messages: UIMessage[], options: SerializeOptions = {}): void {
	const printWindow = window.open('', '_blank');
	if (!printWindow) {
		return;
	}
	printWindow.document.write(buildChatDocument(metadata, messages, options));
	printWindow.document.close();
	printWindow.focus();
	setTimeout(() => printWindow.print(), 250);
}

/** Renders the full conversation to a self-contained, printable HTML document. */
function buildChatDocument(metadata: ChatMetadata, messages: UIMessage[], options: SerializeOptions): string {
	const title = metadata.title?.trim() || 'nao chat';
	const turns = messages
		.map((message) => renderTurn(message, options))
		.filter((turn): turn is string => Boolean(turn))
		.join('\n');

	return `<!doctype html>
<html lang="en">
	<head>
		<meta charset="utf-8" />
		<meta name="viewport" content="width=device-width,initial-scale=1" />
		<title>${escapeHtml(title)}</title>
		<style>${DOCUMENT_STYLES}</style>
	</head>
	<body>
		<header class="chat-header">
			<h1>${escapeHtml(title)}</h1>
			<div class="chat-meta">${renderMeta(metadata)}</div>
		</header>
		<main class="chat">${turns}</main>
	</body>
</html>`;
}

function renderTurn(message: UIMessage, options: SerializeOptions): string | null {
	const body = markdownToHtml(getMessageMarkdown(message, options));
	if (!body) {
		return null;
	}
	const isUser = message.role === 'user';
	const label = isUser ? 'You' : 'nao';
	return `<article class="turn ${isUser ? 'turn-user' : 'turn-assistant'}">
			<div class="turn-role">${label}</div>
			<div class="turn-body nao-md">${body}</div>
		</article>`;
}

function renderMeta(metadata: ChatMetadata): string {
	const parts: string[] = [];
	if (metadata.createdAt) {
		parts.push(`Created ${escapeHtml(formatTimestamp(metadata.createdAt))}`);
	}
	if (metadata.updatedAt) {
		parts.push(`Last updated ${escapeHtml(formatTimestamp(metadata.updatedAt))}`);
	}
	parts.push(`Exported ${escapeHtml(formatTimestamp(Date.now()))}`);
	return parts.join(' &middot; ');
}

const safeRenderer = new Renderer();
safeRenderer.html = () => '';

function markdownToHtml(markdown: string): string {
	if (!markdown.trim()) {
		return '';
	}
	return marked.parse(markdown, { async: false, renderer: safeRenderer }) as string;
}

function formatTimestamp(ms: number): string {
	return new Date(ms).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
}

function escapeHtml(value: string): string {
	return value
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;');
}

/** Turns a chat title into a safe file slug. */
export function toFileSlug(title: string | undefined, fallback = 'nao-chat'): string {
	const slug = (title ?? '')
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, '-')
		.replace(/^-+|-+$/g, '');
	return slug || fallback;
}

